    <script>
        const mockMemberData = {
            "12345": "John Doe, active member",
            "54321": "Jane Smith, inactive member"
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');
            if (mockMemberData[memberId]) {
                memberDetails.textContent = mockMemberData[memberId];
            } else {
                memberDetails.textContent = 'Member not found';
            }
        }

        function submitForm(event) {
            event.preventDefault();
            const fileList = document.getElementById('documents');
            const fileNames = [];
            for (let i = 0; i < fileList.files.length; i++) {
                fileNames.push(fileList.files[i].name);
            }
            document.getElementById('file-list').textContent = fileNames.join(', ');
            document.getElementById('claim-form').style.display = 'none';
            document.getElementById('confirmation').style.display = 'block';
            document.getElementById('reference-number').textContent = 'MS-2026-08-' + Math.floor(Math.random() * 9000 + 1000);
        }
    </script>
